assert len(DATA) == len(CASES)
for d, cid in zip(DATA, CASES):
    assert d["case_id"] == cid, (d["case_id"], cid)
    p = BASE / f"{cid}.json"
    p.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")

# self-verify by re-reading
n=0; cm=ru=di=0
for cid in CASES:
    p = BASE / f"{cid}.json"
    d = json.loads(p.read_text(encoding="utf-8"))
    assert d["case_id"] == cid == p.stem
    for f in ("case_id","prediction_text","basis","confidence","trigger"):
        assert f in d, (cid,f)
    assert 0 <= d["confidence"] <= 1
    t=d["trigger"]
    for b in ("changed_main","reserve_used","disputed"):
        assert isinstance(t[b], bool)
    assert isinstance(t["reason"], str)
    cm += t["changed_main"]; ru += t["reserve_used"]; di += t["disputed"]
    n+=1
print(f"written={n} changed_main={cm} reserve_used={ru} disputed={di}")
